"""Excel-compatible calculation; no CAD, spreadsheet, or optimizer dependency.

All fitting uses dimensionless coordinates. The fitted length is a diagnostic,
never a constraint. See docs/MATHEMATICS.md for the precise sampling contract.
"""
import math

PI = math.pi


def _number(value, name, minimum, maximum):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise ValueError(name + ' must be a finite number')
    if not math.isfinite(value) or not minimum <= value <= maximum:
        raise ValueError(name + ' outside supported source-preview range')


def _segments(n):
    if isinstance(n, bool) or not isinstance(n, int) or n < 100 or n > 20000 or n % 2:
        raise ValueError('segments must be an even integer from 100 to 20000')


def cosine_polygon(amplitude, l2, segments=1000):
    """Length of exactly N chords at x=i*l2/N (not the analytic arc)."""
    _number(amplitude, 'amplitude', 0, 1e6)
    _number(l2, 'l2', .001, 1e6)
    _segments(segments)
    a = amplitude / l2
    old = 0.0
    total = 0.0
    for i in range(1, segments + 1):
        y = 2 * a * math.sin(PI * i / segments) ** 2
        total += math.hypot(1 / segments, y - old)
        old = y
    return total * l2


def _amplitude(ratio, n):
    factors = [2 * math.sin(PI * i / n) ** 2 for i in range(n + 1)]
    differences = [factors[i] - factors[i-1] for i in range(1, n+1)]
    low, high = 0.0, ratio / 4
    for _ in range(64):
        a = (low + high) / 2
        length = sum(math.hypot(1 / n, a * dy) for dy in differences)
        if length < ratio:
            low = a
        else:
            high = a
    return (low + high) / 2


def _parameters(q, phi):
    radius = q / (4 * math.sin(phi))
    first = q / 4
    second = .5 - first
    height = .5 * (1-q) * math.tan(phi) + .5 * q * math.tan(phi/2)
    return radius, first, second, height


def _ordinate(u, radius, first, second, height, slope, start_y):
    # Rationalized circle sag avoids catastrophic subtraction near the flat case.
    if u < first:
        return u*u / (radius + math.sqrt(max(0.0, radius*radius-u*u)))
    if u <= second:
        return start_y + (u-first)*slope
    d = .5-u
    return height - d*d / (radius + math.sqrt(max(0.0, radius*radius-d*d)))


def profile_y(x, l2, radius, phi):
    """Symmetric three-circle/two-tangent graph; phi in radians."""
    _number(l2, 'l2', .001, 1e6)
    _number(x, 'x', 0, l2)
    _number(radius, 'radius', 1e-100, 1e100)
    _number(phi, 'phi', 1e-100, PI/2-1e-6)
    q = 4 * radius / l2 * math.sin(phi)
    if q > 1:
        raise ValueError('negative tangent length')
    r, first, second, h = _parameters(q, phi)
    u = min(x, l2-x)/l2
    start_y = 2*r*math.sin(phi/2)**2
    return l2 * _ordinate(u, r, first, second, h, math.tan(phi), start_y)


def _simplex(objective, q):
    vertices = [[q,1.0],[q+.05,1.0],[q,1.1]]
    scores = [objective(v) for v in vertices]
    for iteration in range(400):
        order = sorted(range(3), key=lambda i: scores[i])
        vertices, scores = [vertices[i] for i in order], [scores[i] for i in order]
        if max(abs(vertices[i][j]-vertices[0][j]) for i in (1,2) for j in (0,1)) < 1e-9:
            return vertices[0], scores[0], iteration
        center = [(vertices[0][j]+vertices[1][j])/2 for j in (0,1)]
        reflected = [2*center[j]-vertices[2][j] for j in (0,1)]
        fr = objective(reflected)
        if fr < scores[0]:
            expanded = [center[j]+2*(reflected[j]-center[j]) for j in (0,1)]
            fe = objective(expanded)
            vertices[2],scores[2] = (expanded,fe) if fe < fr else (reflected,fr)
        elif fr < scores[1]:
            vertices[2],scores[2] = reflected,fr
        else:
            outside = fr < scores[2]
            target = reflected if outside else vertices[2]
            contracted = [(center[j]+target[j])/2 for j in (0,1)]
            fc = objective(contracted)
            if fc < (fr if outside else scores[2]):
                vertices[2],scores[2] = contracted,fc
            else:
                for i in (1,2):
                    vertices[i] = [(vertices[0][j]+vertices[i][j])/2 for j in (0,1)]
                    scores[i] = objective(vertices[i])
    raise ArithmeticError('form fit did not converge; no result released')


def calculate(l1, l2, thickness=None, segments=1000):
    """Return mm/degree/% diagnostics for 1 <= l1/l2 <= 2.

    Exact flat input is supported. Optional thickness is used only for the very
    simplified t/(2r) strain estimate; no material or crack-safety conclusion.
    """
    _number(l1, 'l1', .001, 1e6)
    _number(l2, 'l2', .001, 1e6)
    if not l2 <= l1 <= 2*l2:
        raise ValueError('source preview requires l2 <= l1 <= 2*l2')
    if thickness is not None:
        _number(thickness, 'thickness', 0, 1e6)
    _segments(segments)
    result = dict(segments=segments, l1_mm=l1, l2_mm=l2)
    if l1 == l2:
        result.update(amplitude_mm=0., radius_mm=None, height_mm=0., phi_deg=0.,
                      straight_mm=l2/2, fit_polygon_mm=l2, fit_analytic_mm=l2,
                      length_error_pct=0., analytic_length_error_pct=0.,
                      rms_form_error_mm=0., max_form_error_mm=0., vertical_sse_mm2=0.,
                      cosine_radius_excel_mm=None, cosine_radius_corrected_mm=None,
                      iterations=0)
        for k in ('arc_strain_pct','cosine_strain_excel_pct','cosine_strain_corrected_pct'):
            result[k] = None if thickness is None else 0.
        return result
    a = _amplitude(l1/l2,segments)
    base_phi = math.atan(2*PI*a)
    us = [i/segments for i in range(segments//2+1)]
    ys = [2*a*math.sin(PI*u)**2 for u in us]
    weights = [2.] * len(us)
    weights[-1] = 1.

    def objective(v):
        q, phi = v[0], v[1]*base_phi
        if not 1e-8 < q < 1-1e-8 or not 0 < phi < PI/2-1e-6:
            return 1e100
        r, first, second, h = _parameters(q,phi)
        slope, start_y = math.tan(phi), 2*r*math.sin(phi/2)**2
        return sum(w*(_ordinate(u,r,first,second,h,slope,start_y)-y)**2
                   for u,y,w in zip(us,ys,weights))

    candidates = [_simplex(objective,q) for q in (.3,.7)]
    best, score, iterations = min(candidates,key=lambda c:c[1])
    q,phi = best[0],best[1]*base_phi
    if q < 1e-6 or q > 1-1e-6:
        raise ArithmeticError('degenerate fit boundary; no result released')
    r, first, second, h = _parameters(q,phi)
    s = (.5-2*r*math.sin(phi))/math.cos(phi)
    sampled = [_ordinate(u,r,first,second,h,math.tan(phi),2*r*math.sin(phi/2)**2) for u in us]
    polygon = 2*sum(math.hypot(1/segments,sampled[i]-sampled[i-1]) for i in range(1,len(us)))
    analytic = 4*r*phi+2*s
    rexcel = 1/(2*PI*PI*a)
    rcorrected = rexcel/2
    result.update(amplitude_mm=a*l2, radius_mm=r*l2, height_mm=h*l2,
                  phi_deg=phi*180/PI, straight_mm=s*l2,
                  fit_polygon_mm=polygon*l2, fit_analytic_mm=analytic*l2,
                  length_error_pct=(polygon*l2/l1-1)*100,
                  analytic_length_error_pct=(analytic*l2/l1-1)*100,
                  rms_form_error_mm=math.sqrt(score/(segments+1))*l2,
                  max_form_error_mm=max(abs(y-z) for y,z in zip(ys,sampled))*l2,
                  vertical_sse_mm2=score*l2*l2, iterations=iterations,
                  cosine_radius_excel_mm=rexcel*l2, cosine_radius_corrected_mm=rcorrected*l2)
    for key, radius in [('arc_strain_pct',r),('cosine_strain_excel_pct',rexcel),('cosine_strain_corrected_pct',rcorrected)]:
        result[key] = None if thickness is None else 100*(thickness/l2)/(2*radius)
    return result

"""Windows dialog adapter for an inlined NX Python journal; NX integration untested.

The generator places the unchanged pure core before this adapter. Only Windows
system DLLs are loaded, at run time. No NX object, file, or geometry is modified.
"""
import re
import struct
import sys

WINDOW_TITLE = 'Faltenrechner - Source Preview - CAD ungetestet'


def parse_decimal(text):
    text=text.strip()
    if len(text)>32 or not re.fullmatch(r'[+-]?[0-9]+(?:[.,][0-9]+)?',text):
        raise ValueError('Zahl mit Punkt oder Komma eingeben; keine Tausendertrennzeichen/Exponenten.')
    return float(text.replace(',','.'))


def format_report(result):
    fields=[('amplitude_mm','A [mm]'),('radius_mm','R [mm]'),('height_mm','Hoehe [mm]'),
            ('phi_deg','Winkel [deg]'),('straight_mm','Gerade je Seite [mm]'),
            ('fit_polygon_mm','Excel-Polygonlaenge [mm]'),('fit_analytic_mm','Analytische Fitlaenge [mm]'),
            ('length_error_pct','Polygon-Laengenabweichung [%]'),
            ('analytic_length_error_pct','Analytische Laengenabweichung [%]'),
            ('rms_form_error_mm','Vertikale Formabweichung RMS [mm]'),
            ('max_form_error_mm','Max. vertikale Formabweichung [mm]'),
            ('cosine_radius_excel_mm','Excel-Kosinusradius [mm]'),
            ('cosine_radius_corrected_mm','Korrigierter Kosinusradius [mm]'),
            ('cosine_strain_excel_pct','Excel-Dehnungsabschaetzung [%]'),
            ('cosine_strain_corrected_pct','Korrigierte Kosinusabschaetzung [%]'),
            ('arc_strain_pct','Kreisbogen-Dehnungsabschaetzung [%]')]
    lines=['Excel: 1000 Segmente; Formfit ohne Laengenbedingung.']
    for key,label in fields:
        value=result[key]
        lines.append(label+': '+('entfaellt / nicht angegeben' if value is None else format(value,'.9f')))
    if abs(result['length_error_pct'])>=.1:
        lines.append('Laengenziel <0.1% NICHT erreicht; Excel-Standard unveraendert.')
    lines.append('Dehnung: stark vereinfachtes t/(2r)-Modell; keine Materialfreigabe oder Risssicherheitsaussage.')
    return '\r\n'.join(lines)


def dialog_template():
    """Standard DLGTEMPLATE + 11 actual controls; DWORD aligned as Win32 requires."""
    def wide(text): return (text+'\0').encode('utf-16-le')
    style=0x80000000|0x00c00000|0x00080000|0x40|0x80|0x800
    data=struct.pack('<IIHhhhh',style,0,11,0,0,468,332)
    data+=b'\0\0\0\0'+wide(WINDOW_TITLE)+struct.pack('<H',9)+wide('Segoe UI')
    child=0x50000000
    tab=0x10000
    # id, standard control class atom, text, x,y,w,h, style, extended style
    controls=[
        (10001,0x82,'Abgewickelte Laenge l1 [mm]',12,12,150,14,0,0),
        (101,0x81,'40',174,10,95,16,tab|0x80,0x200),
        (10002,0x82,'Projizierte Breite l2 [mm]',12,36,150,14,0,0),
        (102,0x81,'30',174,34,95,16,tab|0x80,0x200),
        (104,0x80,'Dickenabschaetzung aktivieren',12,60,250,14,tab|3,0),
        (10003,0x82,'Wanddicke [mm]',12,84,150,14,0,0),
        (103,0x81,'2',174,82,95,16,tab|0x80,0x200),
        (1,0x80,'Berechnen',304,10,68,20,tab|1,0),
        (2,0x80,'Schliessen',382,10,72,20,tab,0),
        (10004,0x82,'SOURCE PREVIEW - NX-Laufzeit/Installation ungetestet',12,110,440,14,0,0),
        (201,0x81,'Berechnen zeigt Ergebnisse. Punkt oder Komma als Dezimaltrenner.',12,132,442,186,
         tab|0x4|0x40|0x800|0x200000|0x100000|0x80,0x200),
    ]
    for ident,atom,text,x,y,w,h,flags,extended in controls:
        data+=b'\0'*((-len(data))%4)
        data+=struct.pack('<IIhhhhH',child|flags,extended,x,y,w,h,ident)
        data+=struct.pack('<HH',0xffff,atom)+wide(text)+b'\0\0'
    return data


def run_dialog(owner=None):
    if sys.platform!='win32':
        raise RuntimeError('Dieser vorbereitete NX-Einstieg benoetigt Windows und Python ctypes.')
    import ctypes
    from ctypes import wintypes as w
    user=ctypes.WinDLL('user32',use_last_error=True)
    kernel=ctypes.WinDLL('kernel32',use_last_error=True)
    callback_type=ctypes.WINFUNCTYPE(ctypes.c_ssize_t,w.HWND,w.UINT,w.WPARAM,w.LPARAM)
    # Explicit pointer-sized types prevent HWND/callback truncation in 64-bit NX.
    user.DialogBoxIndirectParamW.argtypes=[w.HINSTANCE,ctypes.c_void_p,w.HWND,callback_type,w.LPARAM]
    user.DialogBoxIndirectParamW.restype=ctypes.c_ssize_t
    user.EndDialog.argtypes=[w.HWND,ctypes.c_ssize_t];user.EndDialog.restype=w.BOOL
    user.GetDlgItemTextW.argtypes=[w.HWND,ctypes.c_int,w.LPWSTR,ctypes.c_int]
    user.GetDlgItemTextW.restype=w.UINT
    user.SetDlgItemTextW.argtypes=[w.HWND,ctypes.c_int,w.LPCWSTR];user.SetDlgItemTextW.restype=w.BOOL
    user.IsDlgButtonChecked.argtypes=[w.HWND,ctypes.c_int];user.IsDlgButtonChecked.restype=w.UINT
    user.GetForegroundWindow.restype=w.HWND
    kernel.GetModuleHandleW.argtypes=[w.LPCWSTR];kernel.GetModuleHandleW.restype=w.HMODULE
    failures=[]

    def read(hwnd,ident):
        text=ctypes.create_unicode_buffer(256)
        user.GetDlgItemTextW(hwnd,ident,text,len(text))
        return parse_decimal(text.value)

    @callback_type
    def callback(hwnd,message,wp,lp):
        try:
            if message==0x110:  # WM_INITDIALOG
                return 1
            if message==0x10 or (message==0x111 and (wp&0xffff)==2):
                user.EndDialog(hwnd,1)
                return 1
            if message==0x111 and (wp&0xffff)==1:  # IDOK: calculate, keep dialog open
                try:
                    thickness=read(hwnd,103) if user.IsDlgButtonChecked(hwnd,104)==1 else None
                    text=format_report(calculate(read(hwnd,101),read(hwnd,102),thickness))
                except (ValueError,ArithmeticError) as exc:
                    text='Fehler: '+str(exc)+'\r\nKein Ergebnis freigegeben.'
                user.SetDlgItemTextW(hwnd,201,text)
                return 1
            return 0
        except Exception as exc:
            # Never let a Python exception escape through a native callback.
            failures.append(str(exc))
            user.EndDialog(hwnd,1)
            return 1

    template=ctypes.create_string_buffer(dialog_template())
    if owner is None: owner=user.GetForegroundWindow()
    value=user.DialogBoxIndirectParamW(kernel.GetModuleHandleW(None),template,owner,callback,0)
    if value in (-1,0): raise ctypes.WinError(ctypes.get_last_error())
    if failures: raise RuntimeError('Dialogfehler: '+failures[0])


if __name__=='__main__':
    run_dialog()
